function App() {
  const builtAt = useMemo(() => new Date().toLocaleTimeString(), []);
  const [requests, setRequests] = useState(0);
  return (
    <div style={{ fontFamily: 'system-ui', padding: 16 }}>
      <h3>SSG: built once, served forever</h3>
      <p>Built at <b>{builtAt}</b> (frozen)</p>
      <p>Served to {requests} request(s) — same HTML each time.</p>
      <button onClick={() => setRequests((n) => n + 1)}>Simulate a request</button>
      <p style={{ fontSize: 12, color: '#666' }}>The build time never changes, however many requests arrive.</p>
    </div>
  );
}

